def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                colors.setdefault(grid[r][c], []).append((r, c))

    boxes = {}
    for color, cells in colors.items():
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = all(
            grid[r][c] == color
            for r in range(r0, r1 + 1)
            for c in range(c0, c1 + 1)
            if r in (r0, r1) or c in (c0, c1)
        )
        if perimeter:
            boxes[color] = (r0, r1, c0, c1)

    source = None
    pattern = None
    for color, (r0, r1, c0, c1) in boxes.items():
        interior = [
            [grid[r][c] == color for c in range(c0 + 1, c1)]
            for r in range(r0 + 1, r1)
        ]
        if any(any(row) for row in interior):
            source = color
            pattern = interior
            break

    out = [[0] * w for _ in range(h)]
    if source is None:
        return out

    pr, pc = len(pattern), len(pattern[0])
    for color, (r0, r1, c0, c1) in boxes.items():
        if color == source:
            for r, c in colors[color]:
                out[r][c] = color
        elif r1 - r0 - 1 == pr and c1 - c0 - 1 == pc:
            for c in range(c0, c1 + 1):
                out[r0][c] = out[r1][c] = color
            for r in range(r0, r1 + 1):
                out[r][c0] = out[r][c1] = color
            for i in range(pr):
                for j in range(pc):
                    if pattern[i][j]:
                        out[r0 + 1 + i][c0 + 1 + j] = color
    return out
